    output[r][c] = 1

block_rows = set(range(2, 9))
block_cols = set(range(9, 16))

# Step 2: Fill block region for block rows with 2s
for r in block_rows:
    for c in block_cols:
        output[r][c] = 2

# Step 3: Fill projected cols for rows after block that have no 1s in block cols
internal_1_col_set = {c for r, c in special_pos if r not in block_rows and c in block_cols}
projected_cols = sorted(block_cols - internal_1_col_set)

for r in range(9, 20):
    has_1_in_block = any(output[r][c] == 1 for c in block_cols)
    if not has_1_in_block:
        for c in projected_cols:
            output[r][c] = 2

# Submit
print(json.dumps({"action": "submit", "grid": output}))

